// ========================================
// CONFIGURABLE VARIABLES — Edit these!
// ========================================
const CONFIG = {
  GITHUB_REPO: 'owner/repository',         // e.g. 'facebook/react'
  GITHUB_TOKEN: 'ghp_your_token_here',     // GitHub Personal Access Token
  CLAUDE_API_KEY: 'sk-ant-your_key_here',  // Anthropic API Key
  DELIVERY_METHOD: 'discord',              // 'discord' OR 'slack' OR 'email'
  DISCORD_WEBHOOK_URL: 'https://discord.com/api/webhooks/YOUR_WEBHOOK',
  SLACK_WEBHOOK_URL: 'https://hooks.slack.com/services/YOUR/SLACK/WEBHOOK',
  EMAIL_RECIPIENT: 'team@yourcompany.com', // Only used if DELIVERY_METHOD = 'email'
  LANGUAGE: 'EN',                          // 'EN' or 'FR'
};

// Calculate date range: last 7 days
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceISO = since.toISOString();
const untilISO = now.toISOString();

return [{
  json: {
    ...CONFIG,
    sinceISO,
    untilISO,
    repoOwner: CONFIG.GITHUB_REPO.split('/')[0],
    repoName: CONFIG.GITHUB_REPO.split('/')[1],
    weekLabel: `${since.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`
  }
}];

const config = $('Set Config & Date Range').item.json;
const sinceDate = new Date(config.sinceISO);

const commitsRaw = $('Fetch Commits').all();
const commits = commitsRaw
  .filter(item => Array.isArray(item.json))
  .flatMap(item => item.json)
  .slice(0, 30)
  .map(c => ({
    sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
    message: c.commit?.message?.split('\n')[0] || 'No message',
    author: c.commit?.author?.name || 'Unknown',
    date: c.commit?.author?.date || ''
  }));

const issuesRaw = $('Fetch Closed Issues').all();
const issues = issuesRaw
  .filter(item => Array.isArray(item.json))
  .flatMap(item => item.json)
  .filter(i => !i.pull_request)
  .filter(i => { if (!i.closed_at) return false; return new Date(i.closed_at) >= sinceDate; })
  .slice(0, 20)
  .map(i => ({ number: i.number, title: i.title, closedBy: i.user?.login || 'Unknown', labels: (i.labels || []).map(l => l.name).join(', ') }));

const prsRaw = $('Fetch Merged PRs').all();
const prs = prsRaw
  .filter(item => Array.isArray(item.json))
  .flatMap(item => item.json)
  .filter(pr => pr.merged_at && new Date(pr.merged_at) >= sinceDate)
  .slice(0, 20)
  .map(pr => ({ number: pr.number, title: pr.title, author: pr.user?.login || 'Unknown', mergedAt: pr.merged_at, additions: pr.additions || 0, deletions: pr.deletions || 0 }));

return [{ json: { repo: config.GITHUB_REPO, weekLabel: config.weekLabel, language: config.LANGUAGE, commitCount: commits.length, issueCount: issues.length, prCount: prs.length, commits, issues, prs, CLAUDE_API_KEY: config.CLAUDE_API_KEY, DELIVERY_METHOD: config.DELIVERY_METHOD, DISCORD_WEBHOOK_URL: config.DISCORD_WEBHOOK_URL, SLACK_WEBHOOK_URL: config.SLACK_WEBHOOK_URL, EMAIL_RECIPIENT: config.EMAIL_RECIPIENT } }];

const data = $input.item.json;
const langInstruction = data.language === 'FR' ? 'Répondez entièrement en français.' : 'Respond entirely in English.';
const commitList = data.commits.map(c => `- [${c.sha}] ${c.message} (by ${c.author})`).join('
') || '(none)';
const issueList = data.issues.map(i => `- #${i.number}: ${i.title} [${i.labels || 'no labels'}]`).join('
') || '(none)';
const prList = data.prs.map(pr => `- #${pr.number}: ${pr.title} by @${pr.author} (+${pr.additions}/-${pr.deletions})`).join('
') || '(none)';
const prompt = `${langInstruction}

You are a senior developer writing the weekly engineering newsletter for the repository: ${data.repo}.
Period covered: ${data.weekLabel}

## COMMITS (${data.commitCount} total, showing up to 30)
${commitList}

## CLOSED ISSUES (${data.issueCount})
${issueList}

## MERGED PULL REQUESTS (${data.prCount})
${prList}

Write a narrative weekly summary (300-500 words) with: 1) catchy headline 2) impactful changes 3) bug fixes 4) patterns 5) motivating closing. Use markdown with emojis.`;
return [{ json: { ...data, prompt } }];

const claudeResponse = $input.item.json;
const prevData = $('Build Claude Prompt').item.json;
const summaryText = claudeResponse.content?.[0]?.text || 'Error: No summary generated';
return [{ json: { summaryText, repo: prevData.repo, weekLabel: prevData.weekLabel, commitCount: prevData.commitCount, issueCount: prevData.issueCount, prCount: prevData.prCount, DELIVERY_METHOD: prevData.DELIVERY_METHOD, DISCORD_WEBHOOK_URL: prevData.DISCORD_WEBHOOK_URL, SLACK_WEBHOOK_URL: prevData.SLACK_WEBHOOK_URL, EMAIL_RECIPIENT: prevData.EMAIL_RECIPIENT } }];

